from itertools import product

# Function to check if a subsequence has an odd sum
def has_odd_sum(subseq):
    return sum(subseq) % 2 == 1

# Check all possible sequences of length up to 6 (since the sum of any subsequence of 1 and 2 cannot exceed 1000)
def count_valid_sequences(length):
    count = 0
    for seq in product([1, 2], repeat=length):
        all_subsequences_have_odd_sum = True
        for i in range(1, length):
            for j in range(i):
                subseq = seq[j:i]
                if not has_odd_sum(subseq):
                    all_subsequences_have_odd_sum = False
                    break
            if not all_subsequences_have_odd_sum:
                break
        if all_subsequences_have_odd_sum:
            count += 1
    return count

# We need to find the maximum length such that the count is less than 1000
max_length = 0
for length in range(1, 10):  # We start with length 1 and go up to 9 (since 2^9 = 512 and 2^10 = 1024)
    if count_valid_sequences(length) < 1000:
        max_length = length
    else:
        break

print(max_length)
